460	  public draw(browserTabId?: string): this {
461	    const libraryCards = this.listLibrary();
462	
463	    if (libraryCards.length === 0) {
464	      throw new Error("Cannot draw: Library is empty");
465	    }
466	
467	    // Find the top card (position 0)
468	    const topCard = libraryCards[0];
469	
470	    // Find the next available hand position
471	    this.addToHand(topCard, browserTabId);
472	
473	    this.validateInvariants();
474	    return this;
475	  }
476	
477	  public playCard(gameCardIndex: number, browserTabId?: string): WhatHappened {
478	    if (gameCardIndex < 0 || gameCardIndex >= this.gameCards.length) {
479	      throw new Error(`Invalid gameCardIndex: ${gameCardIndex}`);
480	    }
481	
482	    const cardToPlay = this.gameCards[gameCardIndex];
483	
484	    if (!isInHand(cardToPlay) && !isRevealed(cardToPlay)) {
485	      throw new Error(`Card at gameCardIndex ${gameCardIndex} is not in hand or revealed`);
486	    }
487	
488	    const cardsToMoveLeft = this.gameCards
489	      .filter((gc) => gc.location.type === cardToPlay.location.type)
490	      .filter((gc) => isInHand(gc) || isRevealed(gc)) // this is for type happiness
491	      .filter((gc) => gc.location.position > cardToPlay.location.position);
492	
493	    // Move card to table
494	    this.moveCard(cardToPlay, { type: "Table" }, browserTabId);
495	
496	    this.validateInvariants();
497	
498	    return {
499	      movedLeft: cardsToMoveLeft,
500	    };
501	  }
502	
503	  public reveal(position: number, browserTabId?: string): this {
504	    const libraryCards = this.listLibrary();
505	    const cardToReveal = libraryCards.find((gc) => (gc.location as LibraryLocation).position === position);
506	
507	    if (!cardToReveal) {
508	      throw new Error(`No card found at library position ${position}`);
509	    }
510	
511	    this.addToRevealed(cardToReveal, browserTabId);
512	
513	    this.validateInvariants();
514	    return this;
515	  }
516	
517	  public revealByGameCardIndex(gameCardIndex: number, browserTabId?: string): this {
518	    const allCards = this.getCards();
519	    if (gameCardIndex < 0 || gameCardIndex >= allCards.length) {
520	      throw new Error(`Invalid game card index: ${gameCardIndex}`);
521	    }
522	
523	    const cardToReveal = allCards[gameCardIndex];
524	
525	    this.addToRevealed(cardToReveal, browserTabId);
526	
527	    this.validateInvariants();
528	    return this;
529	  }
530	
531	  public putInHandByGameCardIndex(gameCardIndex: number, browserTabId?: string): this {
532	    const allCards = this.getCards();
533	    if (gameCardIndex < 0 || gameCardIndex >= allCards.length) {
534	      throw new Error(`Invalid game card index: ${gameCardIndex}`);
535	    }
536	
537	    const cardToPutInHand = allCards[gameCardIndex];
538	
539	    this.addToHand(cardToPutInHand, browserTabId);
540	
541	    this.validateInvariants();
542	    return this;
543	  }
544	
545	  public putOnTopByGameCardIndex(gameCardIndex: number, browserTabId?: string): this {
546	    const allCards = this.getCards();
547	    if (gameCardIndex < 0 || gameCardIndex >= allCards.length) {
548	      throw new Error(`Invalid game card index: ${gameCardIndex}`);
549	    }
550	
551	    const cardToPutOnTop = allCards[gameCardIndex];
552	
553	    this.addToTopOfLibrary(cardToPutOnTop, browserTabId);
554	
555	    this.validateInvariants();
556	    return this;
557	  }
