559	  public putOnBottomByGameCardIndex(gameCardIndex: number, browserTabId?: string): this {
560	    const allCards = this.getCards();
561	    if (gameCardIndex < 0 || gameCardIndex >= allCards.length) {
562	      throw new Error(`Invalid game card index: ${gameCardIndex}`);
563	    }
564	
565	    const cardToPutOnBottom = allCards[gameCardIndex];
566	
567	    this.addToBottomOfLibrary(cardToPutOnBottom, browserTabId);
568	
569	    this.validateInvariants();
570	    return this;
571	  }
572	
573	  public moveHandCard(fromHandPosition: number, toHandPosition: number, browserTabId?: string): WhatHappened {
574	    function nameAndPosition(gameCard: GameCard) {
575	      return `${gameCard.card.name} (${(gameCard.location as HandLocation).position})`;
576	    }
577	    const span = trace.getActiveSpan();
578	    const handCards = this.listHand();
579	    span?.setAttributes({
580	      "game.hand_position.from": fromHandPosition,
581	      "game.hand_position.to": toHandPosition,
582	      "game.hand.begin": JSON.stringify(handCards.map(nameAndPosition), null, 2),
583	    });
584	
585	    if (fromHandPosition < 0 || fromHandPosition >= handCards.length) {
586	      throw new Error(`Invalid fromHandPosition: ${fromHandPosition}`);
587	    }
588	    if (toHandPosition < 0 || toHandPosition >= handCards.length) {
589	      throw new Error(`Invalid toHandPosition: ${toHandPosition}`);
590	    }
591	    if (fromHandPosition === toHandPosition) {
592	      throw new Error(`Cannot move card to same position: ${fromHandPosition}`);
593	    }
594	
595	    const cardToMove = handCards[fromHandPosition];
596	    let newPosition: number;
597	
598	    // Calculate new fractional position
599	    if (toHandPosition === 0) {
600	      // Moving to start
601	      newPosition = handCards[0].location.position - 1;
602	    } else if (toHandPosition === handCards.length - 1) {
603	      // Moving to end
604	      newPosition = handCards[handCards.length - 1].location.position + 1;
605	    } else {
606	      // Moving between cards
607	      // When moving right, insert after toHandPosition
608	      // When moving left, insert before toHandPosition
609	      if (fromHandPosition < toHandPosition) {
610	        // Moving right: insert after toHandPosition
611	        const leftCard = handCards[toHandPosition];
612	        const rightCard = handCards[toHandPosition + 1];
613	        if (rightCard) {
614	          newPosition = (leftCard.location.position + rightCard.location.position) / 2;
615	        } else {
616	          newPosition = leftCard.location.position + 1;
617	        }
618	      } else {
619	        // Moving left: insert before toHandPosition
620	        const rightCard = handCards[toHandPosition];
621	        const leftCard = handCards[toHandPosition - 1];
622	        newPosition = (leftCard.location.position + rightCard.location.position) / 2;
623	      }
624	    }
625	
626	    const move: CardMove = {
627	      gameCardIndex: cardToMove.gameCardIndex,
628	      fromLocation: cardToMove.location,
629	      toLocation: { type: "Hand", position: newPosition },
630	    };
631	    this.executeMove(move, true, browserTabId);
632	
633	    this.validateInvariants();
634	
635	    // Determine which cards shifted for animation
636	    const movedLeft: GameCard[] = [];
637	    const movedRight: GameCard[] = [];
638	
639	    // Cards that shifted depend on direction of move
640	    if (fromHandPosition < toHandPosition) {
641	      // Moved right: cards between old and new position moved left
642	      for (let i = fromHandPosition + 1; i <= toHandPosition; i++) {
643	        movedLeft.push(handCards[i]);
644	      }
645	    } else {
646	      // Moved left: cards between new and old position moved right
647	      for (let i = toHandPosition; i < fromHandPosition; i++) {
648	        movedRight.push(handCards[i]);
649	      }
650	    }
651	
652	    const whatHappened = {
653	      movedLeft: movedLeft.length > 0 ? movedLeft : undefined,
654	      movedRight: movedRight.length > 0 ? movedRight : undefined,
655	      dropppedFromLeft: fromHandPosition > toHandPosition ? cardToMove : undefined,
656	      dropppedFromRight: fromHandPosition < toHandPosition ? cardToMove : undefined,
657	    };
658	    span?.setAttributes({
659	      "game.whatHappened": JSON.stringify(whatHappened, null, 2),
660	      "game.hand.end": JSON.stringify(this.listHand().map(nameAndPosition), null, 2),
661	    });
662	    return whatHappened;
663	  }
664	
665	  public flipCard(gameCardIndex: number, browserTabId?: string): WhatHappened {
666	    const gameCard = this.gameCards[gameCardIndex];
667	    if (!gameCard) {
668	      throw new Error(`Game card with index ${gameCardIndex} not found`);
669	    }
670	
671	    if (!gameCard.card.twoFaced) {
672	      throw new Error(`Card ${gameCard.card.name} is not a two-faced card`);
673	    }
674	
675	    const newFace = gameCard.currentFace === "front" ? "back" : "front";
676	    if (gameCard.currentFace === newFace) {
677	      warn(`Card ${gameCard.card.name} is already on face ${newFace}`);
678	    }
679	
680	    // Update the current face without recording an event
681	    gameCard.currentFace = newFace;
682	    return {};
683	  }
684	
685	  public findCardByIndex(gameCardIndex: number): GameCard | null {
686	    if (gameCardIndex < 0 || gameCardIndex >= this.gameCards.length) {
687	      return null;
688	    }
689	    return this.gameCards[gameCardIndex];
690	  }
691	
692	  public findPrevCardInZone(currentCardIndex: number): number | null {
693	    const currentCard = this.findCardByIndex(currentCardIndex);
694	    if (!currentCard) {
695	      return null;
696	    }
697	
698	    const location = currentCard.location;
699	
700	    // Table cards don't have position ordering
701	    if (location.type === "Table") {
702	      return null;
703	    }
704	
705	    // Get the ordered list of cards in the same zone
706	    let cardsInZone: readonly GameCard[];
707	    if (location.type === "Library") {
708	      cardsInZone = this.listLibrary();
709	    } else if (location.type === "Hand") {
710	      cardsInZone = this.listHand();
711	    } else if (location.type === "Revealed") {
712	      cardsInZone = this.listRevealed();
713	    } else if (location.type === "CommandZone") {
714	      cardsInZone = this.listCommandZone();
715	    } else {
716	      return null;
717	    }
718	
719	    // Find the current card's position in the ordered list
720	    const currentPosition = cardsInZone.findIndex(gc => gc.gameCardIndex === currentCardIndex);
721	    if (currentPosition === -1 || currentPosition === 0) {
722	      return null; // Card not found or is first card
723	    }
724	
725	    // Return the previous card's index
726	    return cardsInZone[currentPosition - 1].gameCardIndex;
727	  }
728	
729	  public findNextCardInZone(currentCardIndex: number): number | null {
730	    const currentCard = this.findCardByIndex(currentCardIndex);
731	    if (!currentCard) {
732	      return null;
733	    }
734	
735	    const location = currentCard.location;
736	
737	    // Table cards don't have position ordering
738	    if (location.type === "Table") {
739	      return null;
740	    }
741	
742	    // Get the ordered list of cards in the same zone
743	    let cardsInZone: readonly GameCard[];
744	    if (location.type === "Library") {
745	      cardsInZone = this.listLibrary();
746	    } else if (location.type === "Hand") {
747	      cardsInZone = this.listHand();
748	    } else if (location.type === "Revealed") {
749	      cardsInZone = this.listRevealed();
750	    } else if (location.type === "CommandZone") {
751	      cardsInZone = this.listCommandZone();
752	    } else {
753	      return null;
754	    }
755	
756	    // Find the current card's position in the ordered list
757	    const currentPosition = cardsInZone.findIndex(gc => gc.gameCardIndex === currentCardIndex);
758	    if (currentPosition === -1 || currentPosition === cardsInZone.length - 1) {
759	      return null; // Card not found or is last card
760	    }
761	
762	    // Return the next card's index
763	    return cardsInZone[currentPosition + 1].gameCardIndex;
764	  }
765	
766	  public undo(gameEventIndex: number, browserTabId?: string): GameState {
767	    const event = this.eventLog.getEvents()[gameEventIndex];
768	
769	    // A mulligan is atomic: reverse every move it made, in reverse order, to
770	    // restore the previous hand and library exactly.
771	    if (event.eventName === "mulligan") {
772	      for (let i = event.moves.length - 1; i >= 0; i--) {
773	        const move = event.moves[i];
774	        this.executeMove({ gameCardIndex: move.gameCardIndex, fromLocation: move.toLocation, toLocation: move.fromLocation }, false);
775	      }
776	      this.eventLog.recordUndo(event, browserTabId);
777	      this.validateInvariants();
778	      return this;
779	    }
780	
781	    const applyToState = this.eventLog.reverse(event);
782	
783	    if (applyToState.eventName === "shuffle library") {
784	      const moves = expandCompactShuffleMoves(applyToState.compactMoves);
785	      moves.forEach((move) => this.executeMove(move, false));
786	    } else if (applyToState.eventName === "move card") {
787	      this.executeMove(applyToState.move, false);
788	    } else {
789	      throw new Error(`Cannot undo event ${event.eventName}`);
790	    }
791	
792	    this.eventLog.recordUndo(event, browserTabId);
793	    return this;
794	  }
795	
796	  public toPersistedGameState(): PersistedGameState {
797	    return {
798	      version: PERSISTED_GAME_STATE_VERSION,
799	      gameId: this.gameId,
800	      status: this.status,
801	      prepId: this.prepId,
802	      prepVersion: this.prepVersion,
803	      deckProvenance: this.deckProvenance,
804	      deckName: this.deckName,
805	      deckId: this.deckId,
806	      totalCards: this.totalCards,
807	      gameCards: dehydrateGameCards(this.gameCards), // Dehydrate to PersistedGameCard[]
808	      events: this.eventLog.getEvents(),
809	    };
810	  }
811	}
812	function warn(message: string) {
813	  console.log(message);
814	}
