import { CardDefinition, DeckProvenance, Deck } from "./types.js";
import {
  PersistedGameState,
  GameId,
  GameStatus,
  CardLocation,
  GameCard,
  LibraryLocation,
  HandLocation,
  RevealedLocation,
  TableLocation,
  CommandZoneLocation,
  PERSISTED_GAME_STATE_VERSION,
  IncompatibleStateVersionError,
  printLocation,
} from "./port-persist-state/types.js";
import { PrepId } from "./port-persist-prep/types.js";
import { CardMove, GameEvent, GameEventLog, StartGameEvent, compactShuffleMoves, expandCompactShuffleMoves } from "./GameEvents.js";
import { trace } from "@opentelemetry/api";
import { CardRepositoryPort } from "./port-card-repository/types.js";
import { hydrateGameCards, dehydrateGameCards } from "./port-card-repository/hydration.js";

export { GameId, GameStatus, CardLocation, GameCard, LibraryLocation, CommandZoneLocation };

class SeededRandom {
  private seed: number;

  constructor(seed: number) {
    this.seed = seed;
  }

  next(): number {
    this.seed = (this.seed * 9301 + 49297) % 233280;
    return this.seed / 233280;
  }
}

// Type guard functions for GameCard location filtering
export function isInLibrary(gameCard: GameCard): gameCard is GameCard & { location: LibraryLocation } {
  return gameCard.location.type === "Library";
}

export function isInHand(gameCard: GameCard): gameCard is GameCard & { location: HandLocation } {
  return gameCard.location.type === "Hand";
}

export function isRevealed(gameCard: GameCard): gameCard is GameCard & { location: RevealedLocation } {
  return gameCard.location.type === "Revealed";
}

export function isOnTable(gameCard: GameCard): gameCard is GameCard & { location: TableLocation } {
  return gameCard.location.type === "Table";
}

export function isInCommandZone(gameCard: GameCard): gameCard is GameCard & { location: CommandZoneLocation } {
  return gameCard.location.type === "CommandZone";
}

/** The number of cards drawn for an opening hand (and on each mulligan). */
export const OPENING_HAND_SIZE = 7;

export interface WhatHappened {
  shuffling?: boolean;
  movedRight?: GameCard[];
  movedLeft?: GameCard[];
  dropppedFromLeft?: GameCard;
  dropppedFromRight?: GameCard;
}

export class GameState {
  public readonly gameId: GameId;
  private status: GameStatus;
  public readonly prepId: PrepId;
  public readonly prepVersion: number;
  public readonly deckProvenance: DeckProvenance;
  public readonly deckName: string;
  public readonly deckId: number; // TODO: remove, once it is no longer used in the UI
  public readonly totalCards: number;
  private readonly gameCards: GameCard[];
  private readonly eventLog: GameEventLog;
  private readonly randomSeed?: number;

  static newGame(gameId: GameId, prepId: PrepId, prepVersion: number, deck: Deck, randomSeed?: number) {
    if (deck.commanders.length > 2) {
      // TODO: make a warning function, somehow get it into WhatHappened?
      console.log("Warning: Deck has more than two commanders. Behavior undefined");
    }

    // Combine all cards and sort alphabetically (maintaining existing invariant)
    const allCards = [...deck.commanders.map((card) => ({ card, isCommander: true })), ...deck.cards.map((card) => ({ card, isCommander: false }))].sort(
      (a, b) => a.card.name.localeCompare(b.card.name)
    );

    let commanderPositionCounter = 0;
    let libraryPositionCounter = 0;

    const gameCards: GameCard[] = allCards.map((item, index) => ({
      card: item.card,
      isCommander: item.isCommander,
      location: item.isCommander
        ? ({ type: "CommandZone", position: commanderPositionCounter++ } as CommandZoneLocation)
        : ({ type: "Library", position: libraryPositionCounter++ } as LibraryLocation),
      gameCardIndex: index,
      currentFace: "front" as const,
    }));

    return new GameState({
      gameId,
      gameStatus: GameStatus.Active,
      prepId,
      prepVersion,
      deckId: deck.id,
      deckName: deck.name,
      deckProvenance: deck.provenance,
      cards: gameCards,
      events: [],
      randomSeed,
    });
  }

  private constructor(params: {
    gameId: GameId;
    gameStatus: GameStatus;
    prepId: PrepId;
    prepVersion: number;
    deckId: number;
    deckName: string;
    deckProvenance: DeckProvenance;
    cards: GameCard[];
    events: GameEvent[];
    randomSeed?: number;
  }) {
    this.gameId = params.gameId;
    this.status = params.gameStatus;
    this.prepId = params.prepId;
    this.prepVersion = params.prepVersion;
    this.deckProvenance = params.deckProvenance;
    this.deckName = params.deckName;
    this.deckId = params.deckId;
    this.totalCards = params.cards.length;
    this.gameCards = params.cards;
    this.eventLog = GameEventLog.fromPersisted(params.events);
    this.randomSeed = params.randomSeed;
  }

  static async fromPersistedGameState(
    psg: PersistedGameState | any,
    cardRepo: CardRepositoryPort
  ): Promise<GameState> {
    // Fail loudly on incompatible versions rather than crashing later with a
    // cryptic "card not found"/JSON error during hydration. Every format before
    // the current one stored card data (inline or in the repository) in a shape
    // this build can no longer read, so there is no safe migration path.
    if (psg.version !== PERSISTED_GAME_STATE_VERSION) {
      throw new IncompatibleStateVersionError(psg.version, PERSISTED_GAME_STATE_VERSION);
    }

    const hydratedGameCards = await hydrateGameCards(psg.gameCards, cardRepo);

    return new GameState({
      ...psg,
      gameStatus: psg.status, // todo: use gameStatus in both places
      cards: hydratedGameCards,
      events: psg.events || [],
    });
  }

  public gameStatus() {
    return this.status;
  }

  public getEventLog() {
    return this.eventLog;
  }

  public getEvent(gameEventIndex: number): GameEvent {
    return this.eventLog.getEvents()[gameEventIndex];
  }

  /**
   * Returns the current state version, which increments on every mutation.
   * Used for optimistic concurrency control to detect stale state.
   */
  public getStateVersion(): number {
    return this.eventLog.getEvents().length;
  }

  private validateInvariants(): void {
    const positionMap = new Map<string, Set<number>>();

    // note that positions must be unique, but they are not required to be a contiguous set. There can be gaps.
    for (const gameCard of this.gameCards) {
      const location = gameCard.location;
      if (location.type !== "Table") {
        const key = location.type;
        if (!positionMap.has(key)) {
          positionMap.set(key, new Set());
        }
        const positions = positionMap.get(key)!;
        if (positions.has(location.position)) {
          throw new Error(`Duplicate position ${location.position} in ${location.type}`);
        }
        positions.add(location.position);
      }
    }

    for (let i = 1; i < this.gameCards.length; i++) {
      const currentCard = this.gameCards[i].card.name;
      const previousCard = this.gameCards[i - 1].card.name;
      if (currentCard.localeCompare(previousCard) < 0) {
        throw new Error(`Cards are not sorted by display name: "${previousCard}" should come after "${currentCard}"`);
      }
    }
  }

  public getCards(): readonly GameCard[] {
    return this.gameCards;
  }

  public listLibrary(): readonly (GameCard & { location: LibraryLocation })[] {
    return this.gameCards.filter(isInLibrary).sort((a, b) => a.location.position - b.location.position);
  }

  public listHand(): readonly (GameCard & { location: HandLocation })[] {
    return this.gameCards.filter(isInHand).sort((a, b) => a.location.position - b.location.position);
  }

  public listRevealed(): readonly (GameCard & { location: RevealedLocation })[] {
    return this.gameCards.filter(isRevealed).sort((a, b) => a.location.position - b.location.position);
  }

  public listTable(): readonly (GameCard & { location: TableLocation })[] {
    return this.gameCards.filter(isOnTable);
  }

  public listCommandZone(): readonly (GameCard & { location: CommandZoneLocation })[] {
    return this.gameCards.filter(isInCommandZone).sort((a, b) => a.location.position - b.location.position);
  }

  public listCommanders(): readonly GameCard[] {
    return this.gameCards.filter((gc) => gc.isCommander);
  }

  public shuffle(browserTabId?: string): WhatHappened {
    const moves = this.shuffleCollectingMoves();
    this.eventLog.record({
      eventName: "shuffle library",
      compactMoves: compactShuffleMoves(moves),
      browserTabId,
    });
    return { shuffling: true };
  }

  /**
   * Fisher-Yates the library and apply the moves WITHOUT recording an event,
   * returning the moves performed. Used both by the public shuffle() (which
   * wraps it in a "shuffle library" event) and by mulligan() (which folds these
   * moves into its single atomic "mulligan" event).
   */
  private shuffleCollectingMoves(): CardMove[] {
    const libraryCards = this.gameCards.filter(isInLibrary);

    // Create random number generator (seeded if randomSeed is provided)
    const random = this.randomSeed !== undefined ? new SeededRandom(this.randomSeed) : null;
    const getRandom = () => (random ? random.next() : Math.random());

    // Fisher-Yates shuffle for the library cards array
    for (let i = libraryCards.length - 1; i > 0; i--) {
      const j = Math.floor(getRandom() * (i + 1));
      [libraryCards[i], libraryCards[j]] = [libraryCards[j], libraryCards[i]];
    }

    const moves: CardMove[] = libraryCards.map((gameCard, index) => ({
      gameCardIndex: gameCard.gameCardIndex,
      fromLocation: gameCard.location,
      toLocation: { type: "Library", position: index },
    }));

    moves.forEach((move) => this.executeMove(move, false));

    this.validateInvariants();

    return moves;
  }

  public startGame(browserTabId?: string): this {
    // Record the start game event and shuffle the library
    // Status is already set to Active when game is created
    this.eventLog.record({ ...StartGameEvent, browserTabId });
    this.shuffle(browserTabId); // We don't need the return value here, just the side effect

    // Deal the opening hand and enter the hand-acceptance (mulligan) stage.
    this.dealOpeningHand(browserTabId);

    return this;
  }

  /**
   * Deal the opening hand as a single atomic "deal opening hand" event carrying
   * its draw moves. Being one event (recorded after the draws) makes it the
   * most-recent live event while the player decides whether to keep — that's how
   * the hand-acceptance stage is derived (see isInHandAcceptanceStage).
   */
  private dealOpeningHand(browserTabId?: string): void {
    const moves = this.drawCardsCollectingMoves(OPENING_HAND_SIZE);
    this.eventLog.record({ eventName: "deal opening hand", moves, browserTabId });
  }

  /**
   * Move up to `count` cards (fewer only for tiny test decks) from the top of
   * the library into the hand WITHOUT recording per-card events, returning the
   * moves. Callers fold these into a single atomic deal/mulligan event.
   */
  private drawCardsCollectingMoves(count: number): CardMove[] {
    const cardsToDraw = Math.min(count, this.listLibrary().length);
    const moves: CardMove[] = [];
    for (let i = 0; i < cardsToDraw; i++) {
      const topCard = this.listLibrary()[0];
      const move: CardMove = {
        gameCardIndex: topCard.gameCardIndex,
        fromLocation: topCard.location,
        toLocation: { type: "Hand", position: this.nextHandPosition() },
      };
      this.executeMove(move, false);
      moves.push(move);
    }
    return moves;
  }

  private nextHandPosition(): number {
    const handCards = this.listHand();
    return handCards.length > 0 ? Math.max(...handCards.map((gc) => gc.location.position)) + 1 : 0;
  }

  private nextLibraryBottomPosition(): number {
    const libraryCards = this.listLibrary();
    return libraryCards.length > 0 ? Math.max(...libraryCards.map((gc) => gc.location.position)) + 1 : 0;
  }

  /**
   * Whether the player is still in the opening-hand acceptance (mulligan) stage.
   * Derived from the event log, so undoing the action that ended the stage
   * brings it back automatically.
   */
  public isInMulliganStage(): boolean {
    return this.eventLog.isInHandAcceptanceStage();
  }

  /** How many mulligans have been taken so far (0 = none). Derived from the log. */
  public getMulliganCount(): number {
    return this.eventLog.mulliganCount();
  }

  /**
   * Mulligan: return the whole hand to the library, shuffle, and redraw a fresh
   * opening hand — recorded as a SINGLE atomic "mulligan" event carrying every
   * move it made. That keeps us in the hand-acceptance stage, bumps the derived
   * mulligan count, and (because it's one event) lets undo reverse the whole
   * mulligan in one step, restoring the previous hand and library exactly.
   */
  public mulligan(browserTabId?: string): WhatHappened {
    const moves: CardMove[] = [];

    // Return every hand card to the bottom of the library, resetting any flipped
    // two-faced cards to their front face (library cards are shown face-down
    // anyway, and a freshly redrawn card should start on its front).
    this.listHand().forEach((gameCard) => {
      gameCard.currentFace = "front";
      const move: CardMove = {
        gameCardIndex: gameCard.gameCardIndex,
        fromLocation: gameCard.location,
        toLocation: { type: "Library", position: this.nextLibraryBottomPosition() },
      };
      this.executeMove(move, false);
      moves.push(move);
    });

    moves.push(...this.shuffleCollectingMoves());
    moves.push(...this.drawCardsCollectingMoves(OPENING_HAND_SIZE));

    this.eventLog.record({ eventName: "mulligan", moves, browserTabId });

    this.validateInvariants();
    return { shuffling: true };
  }

  /**
   * Grouch if the card isn't where it's supposed to be, then move it. Record the event.
   * @param move
   * @param recording - Shuffling or un-shuffling sets it to false, since that's recorded in its own way.
   * @param browserTabId - Optional browser tab identifier for event tracking
   */
  private executeMove(move: CardMove, recording: boolean = true, browserTabId?: string) {
    function verifyLocationsAreIdentical(expected: CardLocation, actual: CardLocation) {
      // hmm, this only matters for UNDO, or any sort of move replay. When I have that, move it
      const identical = expected.type == actual.type && (expected as any).position == (expected as any).position;
      if (!identical) {
        warn(
          `Warning! I'm supposed to move card ${move.gameCardIndex} (${gameCard.card.name}) from ${printLocation(
            move.toLocation
          )} but I found it in ${printLocation(gameCard.location)} `
        );
      }
    }
    const gameCard = this.gameCards[move.gameCardIndex];
    verifyLocationsAreIdentical(move.fromLocation, gameCard.location);
    gameCard.location = move.toLocation;
    if (recording) {
      this.eventLog.record({ eventName: "move card", move, browserTabId });
    }
  }
  // TODO: parallel moveCard for flipCard

  private moveCard(gameCard: GameCard, toLocation: CardLocation, browserTabId?: string) {
    const move = {
      gameCardIndex: gameCard.gameCardIndex,
      fromLocation: gameCard.location,
      toLocation,
    };
    return this.executeMove(move, true, browserTabId);
  }

  private addToRevealed(gameCard: GameCard, browserTabId?: string): this {
    const revealedCards = this.listRevealed();
    const maxPosition = revealedCards.length > 0 ? Math.max(...revealedCards.map((gc) => gc.location.position)) : -1;
    const nextPosition = maxPosition + 1;
    this.moveCard(gameCard, { type: "Revealed", position: nextPosition }, browserTabId);
    return this;
  }

  private addToHand(gameCard: GameCard, browserTabId?: string): this {
    const handCards = this.listHand();
    const maxHandPosition = handCards.length > 0 ? Math.max(...handCards.map((gc) => gc.location.position)) : -1;
    const nextHandPosition = maxHandPosition + 1;
    this.moveCard(gameCard, { type: "Hand", position: nextHandPosition }, browserTabId);
    return this;
  }

  private addToTopOfLibrary(gameCard: GameCard, browserTabId?: string): this {
    const libraryCards = this.listLibrary();

    // Shift all existing library cards down by 1 position
    libraryCards.forEach((libCard) => {
      (libCard.location as LibraryLocation).position += 1;
    });

    // Put the new card at position 0 (top of library)
    this.moveCard(gameCard, { type: "Library", position: 0 }, browserTabId);
    return this;
  }

  private addToBottomOfLibrary(gameCard: GameCard, browserTabId?: string): this {
    const libraryCards = this.listLibrary();
    const maxLibraryPosition = libraryCards.length > 0 ? Math.max(...libraryCards.map((gc) => gc.location.position)) : -1;
    const nextLibraryPosition = maxLibraryPosition + 1;
    this.moveCard(gameCard, { type: "Library", position: nextLibraryPosition }, browserTabId);
    return this;
  }

  public draw(browserTabId?: string): this {
    const libraryCards = this.listLibrary();

    if (libraryCards.length === 0) {
      throw new Error("Cannot draw: Library is empty");
    }

    // Find the top card (position 0)
    const topCard = libraryCards[0];

    // Find the next available hand position
    this.addToHand(topCard, browserTabId);

    this.validateInvariants();
    return this;
  }

  public playCard(gameCardIndex: number, browserTabId?: string): WhatHappened {
    if (gameCardIndex < 0 || gameCardIndex >= this.gameCards.length) {
      throw new Error(`Invalid gameCardIndex: ${gameCardIndex}`);
    }

    const cardToPlay = this.gameCards[gameCardIndex];

    if (!isInHand(cardToPlay) && !isRevealed(cardToPlay)) {
      throw new Error(`Card at gameCardIndex ${gameCardIndex} is not in hand or revealed`);
    }

    const cardsToMoveLeft = this.gameCards
      .filter((gc) => gc.location.type === cardToPlay.location.type)
      .filter((gc) => isInHand(gc) || isRevealed(gc)) // this is for type happiness
      .filter((gc) => gc.location.position > cardToPlay.location.position);

    // Move card to table
    this.moveCard(cardToPlay, { type: "Table" }, browserTabId);

    this.validateInvariants();

    return {
      movedLeft: cardsToMoveLeft,
    };
  }

  public reveal(position: number, browserTabId?: string): this {
    const libraryCards = this.listLibrary();
    const cardToReveal = libraryCards.find((gc) => (gc.location as LibraryLocation).position === position);

    if (!cardToReveal) {
      throw new Error(`No card found at library position ${position}`);
    }

    this.addToRevealed(cardToReveal, browserTabId);

    this.validateInvariants();
    return this;
  }

  public revealByGameCardIndex(gameCardIndex: number, browserTabId?: string): this {
    const allCards = this.getCards();
    if (gameCardIndex < 0 || gameCardIndex >= allCards.length) {
      throw new Error(`Invalid game card index: ${gameCardIndex}`);
    }

    const cardToReveal = allCards[gameCardIndex];

    this.addToRevealed(cardToReveal, browserTabId);

    this.validateInvariants();
    return this;
  }

  public putInHandByGameCardIndex(gameCardIndex: number, browserTabId?: string): this {
    const allCards = this.getCards();
    if (gameCardIndex < 0 || gameCardIndex >= allCards.length) {
      throw new Error(`Invalid game card index: ${gameCardIndex}`);
    }

    const cardToPutInHand = allCards[gameCardIndex];

    this.addToHand(cardToPutInHand, browserTabId);

    this.validateInvariants();
    return this;
  }

  public putOnTopByGameCardIndex(gameCardIndex: number, browserTabId?: string): this {
    const allCards = this.getCards();
    if (gameCardIndex < 0 || gameCardIndex >= allCards.length) {
      throw new Error(`Invalid game card index: ${gameCardIndex}`);
    }

    const cardToPutOnTop = allCards[gameCardIndex];

    this.addToTopOfLibrary(cardToPutOnTop, browserTabId);

    this.validateInvariants();
    return this;
  }

  public putOnBottomByGameCardIndex(gameCardIndex: number, browserTabId?: string): this {
    const allCards = this.getCards();
    if (gameCardIndex < 0 || gameCardIndex >= allCards.length) {
      throw new Error(`Invalid game card index: ${gameCardIndex}`);
    }

    const cardToPutOnBottom = allCards[gameCardIndex];

    this.addToBottomOfLibrary(cardToPutOnBottom, browserTabId);

    this.validateInvariants();
    return this;
  }

  public moveHandCard(fromHandPosition: number, toHandPosition: number, browserTabId?: string): WhatHappened {
    function nameAndPosition(gameCard: GameCard) {
      return `${gameCard.card.name} (${(gameCard.location as HandLocation).position})`;
    }
    const span = trace.getActiveSpan();
    const handCards = this.listHand();
    span?.setAttributes({
      "game.hand_position.from": fromHandPosition,
      "game.hand_position.to": toHandPosition,
      "game.hand.begin": JSON.stringify(handCards.map(nameAndPosition), null, 2),
    });

    if (fromHandPosition < 0 || fromHandPosition >= handCards.length) {
      throw new Error(`Invalid fromHandPosition: ${fromHandPosition}`);
    }
    if (toHandPosition < 0 || toHandPosition >= handCards.length) {
      throw new Error(`Invalid toHandPosition: ${toHandPosition}`);
    }
    if (fromHandPosition === toHandPosition) {
      throw new Error(`Cannot move card to same position: ${fromHandPosition}`);
    }

    const cardToMove = handCards[fromHandPosition];
    let newPosition: number;

    // Calculate new fractional position
    if (toHandPosition === 0) {
      // Moving to start
      newPosition = handCards[0].location.position - 1;
    } else if (toHandPosition === handCards.length - 1) {
      // Moving to end
      newPosition = handCards[handCards.length - 1].location.position + 1;
    } else {
      // Moving between cards
      // When moving right, insert after toHandPosition
      // When moving left, insert before toHandPosition
      if (fromHandPosition < toHandPosition) {
        // Moving right: insert after toHandPosition
        const leftCard = handCards[toHandPosition];
        const rightCard = handCards[toHandPosition + 1];
        if (rightCard) {
          newPosition = (leftCard.location.position + rightCard.location.position) / 2;
        } else {
          newPosition = leftCard.location.position + 1;
        }
      } else {
        // Moving left: insert before toHandPosition
        const rightCard = handCards[toHandPosition];
        const leftCard = handCards[toHandPosition - 1];
        newPosition = (leftCard.location.position + rightCard.location.position) / 2;
      }
    }

    const move: CardMove = {
      gameCardIndex: cardToMove.gameCardIndex,
      fromLocation: cardToMove.location,
      toLocation: { type: "Hand", position: newPosition },
    };
    this.executeMove(move, true, browserTabId);

    this.validateInvariants();

    // Determine which cards shifted for animation
    const movedLeft: GameCard[] = [];
    const movedRight: GameCard[] = [];

    // Cards that shifted depend on direction of move
    if (fromHandPosition < toHandPosition) {
      // Moved right: cards between old and new position moved left
      for (let i = fromHandPosition + 1; i <= toHandPosition; i++) {
        movedLeft.push(handCards[i]);
      }
    } else {
      // Moved left: cards between new and old position moved right
      for (let i = toHandPosition; i < fromHandPosition; i++) {
        movedRight.push(handCards[i]);
      }
    }

    const whatHappened = {
      movedLeft: movedLeft.length > 0 ? movedLeft : undefined,
      movedRight: movedRight.length > 0 ? movedRight : undefined,
      dropppedFromLeft: fromHandPosition > toHandPosition ? cardToMove : undefined,
      dropppedFromRight: fromHandPosition < toHandPosition ? cardToMove : undefined,
    };
    span?.setAttributes({
      "game.whatHappened": JSON.stringify(whatHappened, null, 2),
      "game.hand.end": JSON.stringify(this.listHand().map(nameAndPosition), null, 2),
    });
    return whatHappened;
  }

  public flipCard(gameCardIndex: number, browserTabId?: string): WhatHappened {
    const gameCard = this.gameCards[gameCardIndex];
    if (!gameCard) {
      throw new Error(`Game card with index ${gameCardIndex} not found`);
    }

    if (!gameCard.card.twoFaced) {
      throw new Error(`Card ${gameCard.card.name} is not a two-faced card`);
    }

    const newFace = gameCard.currentFace === "front" ? "back" : "front";
    if (gameCard.currentFace === newFace) {
      warn(`Card ${gameCard.card.name} is already on face ${newFace}`);
    }

    // Update the current face without recording an event
    gameCard.currentFace = newFace;
    return {};
  }

  public findCardByIndex(gameCardIndex: number): GameCard | null {
    if (gameCardIndex < 0 || gameCardIndex >= this.gameCards.length) {
      return null;
    }
    return this.gameCards[gameCardIndex];
  }

  public findPrevCardInZone(currentCardIndex: number): number | null {
    const currentCard = this.findCardByIndex(currentCardIndex);
    if (!currentCard) {
      return null;
    }

    const location = currentCard.location;

    // Table cards don't have position ordering
    if (location.type === "Table") {
      return null;
    }

    // Get the ordered list of cards in the same zone
    let cardsInZone: readonly GameCard[];
    if (location.type === "Library") {
      cardsInZone = this.listLibrary();
    } else if (location.type === "Hand") {
      cardsInZone = this.listHand();
    } else if (location.type === "Revealed") {
      cardsInZone = this.listRevealed();
    } else if (location.type === "CommandZone") {
      cardsInZone = this.listCommandZone();
    } else {
      return null;
    }

    // Find the current card's position in the ordered list
    const currentPosition = cardsInZone.findIndex(gc => gc.gameCardIndex === currentCardIndex);
    if (currentPosition === -1 || currentPosition === 0) {
      return null; // Card not found or is first card
    }

    // Return the previous card's index
    return cardsInZone[currentPosition - 1].gameCardIndex;
  }

  public findNextCardInZone(currentCardIndex: number): number | null {
    const currentCard = this.findCardByIndex(currentCardIndex);
    if (!currentCard) {
      return null;
    }

    const location = currentCard.location;

    // Table cards don't have position ordering
    if (location.type === "Table") {
      return null;
    }

    // Get the ordered list of cards in the same zone
    let cardsInZone: readonly GameCard[];
    if (location.type === "Library") {
      cardsInZone = this.listLibrary();
    } else if (location.type === "Hand") {
      cardsInZone = this.listHand();
    } else if (location.type === "Revealed") {
      cardsInZone = this.listRevealed();
    } else if (location.type === "CommandZone") {
      cardsInZone = this.listCommandZone();
    } else {
      return null;
    }

    // Find the current card's position in the ordered list
    const currentPosition = cardsInZone.findIndex(gc => gc.gameCardIndex === currentCardIndex);
    if (currentPosition === -1 || currentPosition === cardsInZone.length - 1) {
      return null; // Card not found or is last card
    }

    // Return the next card's index
    return cardsInZone[currentPosition + 1].gameCardIndex;
  }

  public undo(gameEventIndex: number, browserTabId?: string): GameState {
    const event = this.eventLog.getEvents()[gameEventIndex];

    // A mulligan is atomic: reverse every move it made, in reverse order, to
    // restore the previous hand and library exactly.
    if (event.eventName === "mulligan") {
      for (let i = event.moves.length - 1; i >= 0; i--) {
        const move = event.moves[i];
        this.executeMove({ gameCardIndex: move.gameCardIndex, fromLocation: move.toLocation, toLocation: move.fromLocation }, false);
      }
      this.eventLog.recordUndo(event, browserTabId);
      this.validateInvariants();
      return this;
    }

    const applyToState = this.eventLog.reverse(event);

    if (applyToState.eventName === "shuffle library") {
      const moves = expandCompactShuffleMoves(applyToState.compactMoves);
      moves.forEach((move) => this.executeMove(move, false));
    } else if (applyToState.eventName === "move card") {
      this.executeMove(applyToState.move, false);
    } else {
      throw new Error(`Cannot undo event ${event.eventName}`);
    }

    this.eventLog.recordUndo(event, browserTabId);
    return this;
  }

  public toPersistedGameState(): PersistedGameState {
    return {
      version: PERSISTED_GAME_STATE_VERSION,
      gameId: this.gameId,
      status: this.status,
      prepId: this.prepId,
      prepVersion: this.prepVersion,
      deckProvenance: this.deckProvenance,
      deckName: this.deckName,
      deckId: this.deckId,
      totalCards: this.totalCards,
      gameCards: dehydrateGameCards(this.gameCards), // Dehydrate to PersistedGameCard[]
      events: this.eventLog.getEvents(),
    };
  }
}
function warn(message: string) {
  console.log(message);
}

