// Store scroll positions before HTMX swaps
let handScrollPosition = 0;
let revealedCardsScrollPosition = 0;

/**
 * Retain scroll position of hand
 */
document.addEventListener("htmx:beforeSwap", function (evt) {
  // Store the current scroll position of the hand section
  const handSection = document.querySelector("#hand-section .hand-cards");
  if (handSection) {
    handScrollPosition = handSection.scrollLeft;
  }

  // Store the current scroll position of the revealed cards section
  const revealedCardsSection = document.querySelector("#revealed-cards-area");
  if (revealedCardsSection) {
    revealedCardsScrollPosition = revealedCardsSection.scrollLeft;
  }
});

document.addEventListener("htmx:afterSwap", function (evt) {
  // Restore the scroll position of the hand section
  const handSection = document.querySelector("#hand-section .hand-cards");
  if (handSection && handScrollPosition > 0) {
    // Only restore if the scroll position is still valid (not beyond the new scroll width)
    const maxScrollLeft = handSection.scrollWidth - handSection.clientWidth;
    handSection.scrollLeft = Math.min(handScrollPosition, Math.max(0, maxScrollLeft));
  }

  // Restore the scroll position of the revealed cards section
  const revealedCardsSection = document.querySelector("#revealed-cards-area");
  if (revealedCardsSection && revealedCardsScrollPosition > 0) {
    // Only restore if the scroll position is still valid (not beyond the new scroll width)
    const maxScrollLeft = revealedCardsSection.scrollWidth - revealedCardsSection.clientWidth;
    revealedCardsSection.scrollLeft = Math.min(revealedCardsScrollPosition, Math.max(0, maxScrollLeft));
  }

  // The new menu markup renders with aria-expanded="false"; re-sync it to the
  // persistent body state (see setMenuOpen below).
  syncMenuToggleAria();
});

/**
 * Hamburger menu toggle.
 *
 * The open/closed state is a class on <body>, which HTMX never swaps. The menu
 * markup itself lives inside #game-container and is replaced on every
 * game-state-updated swap, so keeping the state on an element that survives
 * swaps avoids racing the swap/settle lifecycle. The toggle uses event
 * delegation on the document so it keeps working after the markup is replaced.
 */
function setMenuOpen(open) {
  document.body.classList.toggle("game-menu-open", open);
  syncMenuToggleAria();
}

function syncMenuToggleAria() {
  const toggle = document.querySelector("#menu-toggle");
  if (toggle) {
    toggle.setAttribute("aria-expanded", document.body.classList.contains("game-menu-open") ? "true" : "false");
  }
}

document.addEventListener("click", function (evt) {
  if (evt.target.closest("#menu-toggle")) {
    setMenuOpen(!document.body.classList.contains("game-menu-open"));
    return;
  }

  // Clicking anywhere outside the open menu closes it. Clicks land on an open
  // modal overlay too (it sits above the panel, outside #game-menu), so opening
  // a modal then interacting with it dismisses the menu underneath.
  if (document.body.classList.contains("game-menu-open") && !evt.target.closest("#game-menu")) {
    setMenuOpen(false);
  }
});

/**
 * Copy card image to clipboard
 */
// Function to copy card image to clipboard using proxy URL
async function copyCardToClipboard(cardId, face) {
  // make sure tracing exists
  Hny = Hny || {
    inSpanAsync: (a, b, fn, c) => {
      console.log("warning: no tracing");
      return fn();
    },
  };
  return Hny.inSpanAsync("mtg-deck-shuffler-web", "copy card to clipboard", async (span) => {
    const proxyUrl = `/proxy-image?cardId=${encodeURIComponent(cardId)}&face=${encodeURIComponent(face)}`;
    const response = await fetch(proxyUrl);
    span?.setAttribute("app.response.ok", response.ok);
    if (response.ok) {
      const blob = await response.blob();
      span?.setAttribute("app.blob.type", blob.type);
      span?.setAttribute("app.blob.size", blob.size);
      await navigator.clipboard.write([
        new ClipboardItem({
          [blob.type]: blob,
        }),
      ]);
      return true;
    }
    return false;
  });
}

// Handle clipboard copying when HTMX is about to make the request
document.addEventListener("htmx:beforeRequest", async function (evt) {
  if (evt.detail.elt.classList.contains("play-button")) {
    const button = evt.detail.elt;
    const cardId = button.dataset.cardId;
    const currentFace = button.dataset.currentFace || "front";

    // Try to copy to clipboard first
    try {
      const success = await copyCardToClipboard(cardId, currentFace);
      if (success) {
        button.textContent = "Copied!";
      } else {
        button.textContent = "Copy failed 😨";
      }
    } catch (clipboardErr) {
      console.warn("Failed to copy image to clipboard:", clipboardErr);
      button.textContent = "Copy failed 😨";
    }

    button.disabled = true;
  }
});

// Function to copy card image to clipboard from modal
window.copyCardImageToClipboard = async function (event, imageUrl, cardName) {
  try {
    // Extract card ID and face from the image URL
    // URL format: https://cards.scryfall.io/large/front/{first}/{second}/{cardId}.jpg
    const urlParts = imageUrl.split("/");
    const filename = urlParts[urlParts.length - 1];
    const cardId = filename.split(".")[0];
    const face = urlParts.includes("/back/") ? "back" : "front";

    const success = await copyCardToClipboard(cardId, face);

    // Show feedback to user
    const copyButton = event.target;
    const originalText = copyButton.textContent;

    if (success) {
      copyButton.textContent = "Copied!";
    } else {
      copyButton.textContent = "Copy failed 😨";
    }
    copyButton.disabled = true;

    setTimeout(() => {
      copyButton.textContent = originalText;
      copyButton.disabled = false;
    }, 2000);
  } catch (error) {
    console.warn("Failed to copy image to clipboard:", error);

    // Show error feedback
    const copyButton = event.target;
    const originalText = copyButton.textContent;
    copyButton.textContent = "Copy failed 😨";
    copyButton.disabled = true;

    setTimeout(() => {
      copyButton.textContent = originalText;
      copyButton.disabled = false;
    }, 2000);
  }
};

/**
 * Drag/drop for hand card rearranging
 */
// Drag-and-drop state
let draggedCard = null;
let draggedFromPosition = null;

// Set up drag-and-drop handlers after HTMX swaps
document.addEventListener("htmx:afterSwap", function (evt) {
  setupHandCardDragAndDrop();
});

// Also set up on initial page load
document.addEventListener("DOMContentLoaded", function () {
  setupHandCardDragAndDrop();
});

function setupHandCardDragAndDrop() {
  const handCards = document.querySelectorAll("#hand-cards .card-container[draggable='true']");
  const dropZones = document.querySelectorAll("#hand-cards .hand-drop-zone");

  handCards.forEach((card) => {
    card.addEventListener("dragstart", handleDragStart);
    card.addEventListener("dragend", handleDragEnd);
  });

  dropZones.forEach((zone) => {
    zone.addEventListener("dragover", handleDragOver);
    zone.addEventListener("dragleave", handleDragLeave);
    zone.addEventListener("drop", handleDrop);
  });
}

function handleDragStart(e) {
  draggedCard = e.currentTarget;
  draggedFromPosition = parseInt(draggedCard.dataset.handPosition);
  draggedCard.classList.add("dragging");

  draggedCard.classList.remove("card-moved-left"); // if it has these it flickers when dropped
  draggedCard.classList.remove("card-moved-right");
  draggedCard.classList.remove("dropped-from-left");
  draggedCard.classList.remove("dropped-from-right");

  e.dataTransfer.effectAllowed = "move";
  e.dataTransfer.setData("text/html", draggedCard.innerHTML);
}

function handleDragEnd(e) {
  draggedCard.classList.remove("dragging");
  draggedCard = null;
  draggedFromPosition = null;
}

function handleDragOver(e) {
  if (e.preventDefault) {
    e.preventDefault();
  }
  e.dataTransfer.dropEffect = "move";
  e.currentTarget.classList.add("drag-over");
  return false;
}

function handleDragLeave(e) {
  e.currentTarget.classList.remove("drag-over");
}

function handleDrop(e) {
  if (e.stopPropagation) {
    e.stopPropagation();
  }
  e.preventDefault();

  const dropZone = e.currentTarget;
  dropZone.classList.remove("drag-over");

  const dropPosition = parseInt(dropZone.dataset.handPosition);

  if (draggedCard && draggedFromPosition !== null) {
    // Calculate the target position
    // If dropping after the dragged card's current position, adjust by -1 (why?)
    let targetPosition = dropPosition;
    if (dropPosition > draggedFromPosition) {
      targetPosition = dropPosition - 1;
    }

    if (draggedFromPosition === targetPosition) {
      return false;
    }

    // Get the game ID and expected version from the page
    const gameContainer = document.querySelector("#game-container");
    const gameId = gameContainer?.dataset.gameId;
    const expectedVersion = gameContainer?.dataset.expectedVersion;

    if (gameId) {
      // Use HTMX to make the POST request
      htmx.ajax("POST", `/move-hand-card/${gameId}/${draggedFromPosition}/${targetPosition}`, {
        target: "#game-container",
        swap: "outerHTML",
        values: { "expected-version": expectedVersion },
      });
    }
  }

  return false;
}

/**
 * Keyboard navigation for card modal
 */
/**
 * Standard undo hotkey (Ctrl+Z / Cmd+Z).
 *
 * Clicks the live undo button rendered inside the (possibly hidden) hamburger
 * menu, so its current event index and expected-version come along for free.
 * Ignored while a modal is open or while typing in a field.
 */
document.addEventListener('keydown', (event) => {
  const isUndo = (event.ctrlKey || event.metaKey) && !event.shiftKey && !event.altKey && event.key.toLowerCase() === 'z';
  if (!isUndo) return;

  // Don't hijack undo inside text inputs or while a modal is focused.
  const target = event.target;
  if (target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable)) return;
  if (document.querySelector('.modal-overlay, .card-modal-overlay')) return;

  const undoButton = document.querySelector('.undo-button');
  if (!undoButton) return;

  event.preventDefault();
  undoButton.click();
});

document.addEventListener('keydown', (event) => {
  // Check if card modal is open
  const modal = document.querySelector('.card-modal-overlay');
  if (!modal) return;

  // Navigate with arrow keys
  if (event.key === 'ArrowLeft') {
    const prevButton = modal.querySelector('.card-modal-nav-prev');
    if (prevButton) {
      prevButton.click();
      event.preventDefault(); // Prevent default arrow key behavior
    }
  } else if (event.key === 'ArrowRight') {
    const nextButton = modal.querySelector('.card-modal-nav-next');
    if (nextButton) {
      nextButton.click();
      event.preventDefault(); // Prevent default arrow key behavior
    }
  }
});

import { GameState, GameCard } from "../../GameState.js";
import { formatCardNameAsModalLink, CardAction } from "../common/shared-components.js";
import { GameEvent } from "../../GameEvents.js";
import { formatGameEventHtmlFragment } from "./history-components.js";

export function formatModalHtmlFragment(title: string, bodyContent: string): string {
  return `<div class="modal-overlay"
               hx-get="/close-modal"
               hx-target="#modal-container"
               hx-swap="innerHTML"
               hx-trigger="click[target==this], keyup[key=='Escape'] from:body"
               tabindex="0">
    <div class="modal-dialog">
      <div class="modal-header">
        <h2 class="modal-title">${title}</h2>
        <button class="modal-close"
                hx-get="/close-modal"
                hx-target="#modal-container"
                hx-swap="innerHTML">&times;</button>
      </div>
      <div class="modal-body">
        ${bodyContent}
      </div>
    </div>
  </div>`;
}

function formatTableCardListHtmlFragment(game: GameState): string {
  const tableCards = game.listTable();
  const expectedVersion = game.getStateVersion();

  return tableCards
    .map(
      (gameCard: any, index: number) =>
        `<li class="table-card-item">
          <div class="card-info">
            ${formatCardNameAsModalLink(gameCard.card.name, game.gameId, gameCard.gameCardIndex, expectedVersion)}
          </div>
        </li>`
    )
    .join("");
}

export function formatTableModalHtmlFragment(game: GameState): string {
  const tableCards = game.listTable();
  const tableCardList = formatTableCardListHtmlFragment(game);

  const bodyContent = `<p class="modal-subtitle">
          ${tableCards.length} cards on table
        </p>
        <ul class="table-search-list">
          ${tableCardList}
        </ul>`;

  return formatModalHtmlFragment("Cards on Table", bodyContent);
}

// Helper function to create modal action button with auto-close
function formatModalActionButton(
  action: string,
  endpoint: string,
  gameId: number,
  cardIndex: number,
  expectedVersion: number,
  title: string,
  cssClass = "modal-action-button",
  cardId?: string,
  currentFace?: "front" | "back"
): string {
  const cardIdAttr = action === "Play" && cardId ? `data-card-id="${cardId}"` : "";
  const faceAttr = action === "Play" && currentFace ? `data-current-face="${currentFace}"` : "";
  const extraAttrs = [cardIdAttr, faceAttr].filter(Boolean).join(" ");
  const swapAttr = `hx-swap="outerHTML"`;

  return `<button class="${cssClass}"
                    hx-post="${endpoint}/${gameId}/${cardIndex}"
                    hx-vals='{"expected-version": ${expectedVersion}}'
                    hx-target="#game-container"
                    ${swapAttr}
                    ${extraAttrs}
                    hx-on::after-request="htmx.ajax('GET', '/close-card-modal', {target: '#card-modal-container', swap: 'innerHTML'}); htmx.ajax('GET', '/close-modal', {target: '#modal-container', swap: 'innerHTML'})"
                    title="${title}">
                 ${action}
               </button>`;
}

// Generate action buttons for cards in hand
function formatModalCardActionsForHand(gameId: number, gameCard: GameCard, expectedVersion: number): string {
  const actions: CardAction[] = [
    { action: "Play", endpoint: "/play-card", title: "Copy image and remove from hand", cssClass: "modal-action-button play-button" },
    { action: "Put on Top", endpoint: "/put-on-top", title: "Move card to top of library", cssClass: "modal-action-button put-on-top-button" },
    { action: "Put on Bottom", endpoint: "/put-on-bottom", title: "Move card to bottom of library", cssClass: "modal-action-button put-on-bottom-button" },
  ];

  return actions
    .map((action) =>
      formatModalActionButton(
        action.action,
        action.endpoint,
        gameId,
        gameCard.gameCardIndex,
        expectedVersion,
        action.title,
        action.cssClass,
        gameCard.card.scryfallId,
        gameCard.currentFace
      )
    )
    .join("");
}

// Generate action buttons for revealed cards
function formatModalCardActionsForRevealed(gameId: number, gameCard: GameCard, expectedVersion: number): string {
  const actions: CardAction[] = [
    { action: "Play", endpoint: "/play-card", title: "Copy image and remove from revealed", cssClass: "modal-action-button play-button" },
    { action: "Put in Hand", endpoint: "/put-in-hand", title: "Move card to hand", cssClass: "modal-action-button put-in-hand-button" },
    { action: "Put on Top", endpoint: "/put-on-top", title: "Move card to top of library", cssClass: "modal-action-button put-on-top-button" },
    { action: "Put on Bottom", endpoint: "/put-on-bottom", title: "Move card to bottom of library", cssClass: "modal-action-button put-on-bottom-button" },
  ];

  return actions
    .map((action) =>
      formatModalActionButton(
        action.action,
        action.endpoint,
        gameId,
        gameCard.gameCardIndex,
        expectedVersion,
        action.title,
        action.cssClass,
        gameCard.card.scryfallId,
        gameCard.currentFace
      )
    )
    .join("");
}

// Generate action buttons for cards in library
function formatModalCardActionsForLibrary(gameId: number, gameCard: GameCard, expectedVersion: number): string {
  const actions: CardAction[] = [
    { action: "Reveal", endpoint: "/reveal-card", title: "Reveal", cssClass: "modal-action-button" },
    { action: "Put in Hand", endpoint: "/put-in-hand", title: "Put in Hand", cssClass: "modal-action-button secondary" },
  ];

  return actions
    .map((action) =>
      formatModalActionButton(
        action.action,
        action.endpoint,
        gameId,
        gameCard.gameCardIndex,
        expectedVersion,
        action.title,
        action.cssClass,
        gameCard.card.scryfallId,
        gameCard.currentFace
      )
    )
    .join("");
}

// Generate action buttons for cards on table
function formatModalCardActionsForTable(gameId: number, gameCard: GameCard, expectedVersion: number): string {
  return formatModalActionButton(
    "Return",
    "/reveal-card",
    gameId,
    gameCard.gameCardIndex,
    expectedVersion,
    "Return to revealed cards",
    "modal-action-button",
    gameCard.card.scryfallId,
    gameCard.currentFace
  );
}

// Get location-specific actions based on card location
export function getModalCardActionsByLocation(gameCard: GameCard, gameId: number, expectedVersion: number): string {
  switch (gameCard.location.type) {
    case "Hand":
      return formatModalCardActionsForHand(gameId, gameCard, expectedVersion);
    case "Revealed":
      return formatModalCardActionsForRevealed(gameId, gameCard, expectedVersion);
    case "Library":
      return formatModalCardActionsForLibrary(gameId, gameCard, expectedVersion);
    case "Table":
      return formatModalCardActionsForTable(gameId, gameCard, expectedVersion);
    case "CommandZone":
      return ""; // No location-specific actions for commanders
    default:
      return "";
  }
}



export function formatLossModalHtmlFragment(): string {
  return formatModalHtmlFragment("☠️ You Lose! ☠️", `<p class="modal-message">You tried to draw from an empty library!</p>`);
}

export function formatStaleStateErrorModal(
  expectedVersion: number,
  currentVersion: number,
  missedEvents: GameEvent[],
  game: GameState
): string {
  const missedEventsHtml = missedEvents.length > 0
    ? `<div style="margin: 1.5rem 0; text-align: left;">
         <h4 style="margin-bottom: 0.5rem; color: #333;">What happened while you were away:</h4>
         <ol class="history-list" style="padding-left: 2rem;">
           ${missedEvents.map((event, index) => `
             <li class="history-item" style="margin-bottom: 0.5rem;">
               <span class="event-number">${expectedVersion + index + 1}.</span>
               ${formatGameEventHtmlFragment(event, game)}
             </li>
           `).join('')}
         </ol>
       </div>`
    : '';

  const bodyContent = `
    <div class="missed-events-modal-content">
    <p>
    Expected version: ${expectedVersion}, Current version: ${currentVersion}
    </p>
    ${missedEventsHtml}
      <button onclick="location.reload()"
              class="modal-action-button recover-button">
        Refresh Page
      </button>
    </div>
  `;

  return formatModalHtmlFragment("⚠️ Game State Changed", bodyContent);
}

